<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Inventory</title><style>body{font:15px Arial;background:#f4f6fa;color:#1b2940;margin:0}.wrap{max-width:1200px;margin:30px auto;padding:0 18px}.card{background:white;padding:22px;border:1px solid #e5eaf1;border-radius:12px;margin:18px 0}a,button{background:#173d65;color:white;padding:10px 14px;border:0;border-radius:7px;text-decoration:none;cursor:pointer}input,select{padding:10px;border:1px solid #ccd5df;border-radius:6px;margin:4px;max-width:100%}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px;border-bottom:1px solid #edf0f4;font-size:14px}.ok{color:#18794e}</style></head><body><main class="wrap"><h1>Branch Inventory</h1><p><a href="{{ route('dashboard') }}">Dashboard</a> <a href="{{ route('inventory.history') }}">Stock Ledger</a> <a href="{{ route('purchases.index') }}">Purchases</a> <a href="{{ route('suppliers.index') }}">Suppliers</a> <a href="{{ route('transfers.index') }}">Transfers</a></p>@if(session('success'))<p class="ok">{{ session('success') }}</p>@endif<div class="card"><form method="GET"><label><input type="checkbox" name="low_stock" value="1" @checked(request('low_stock'))> Low stock only</label>@if(auth()->user()->hasRole('owner'))<select name="branch_id"><option value="">All branches</option>@foreach($branches as $b)<option value="{{ $b->id }}" @selected((string)$branchId===(string)$b->id)>{{ $b->name }}</option>@endforeach</select>@endif<button>Filter</button></form></div><div class="card"><h2>Adjust Stock</h2><form method="POST" action="{{ route('inventory.adjust') }}">@csrf @if(auth()->user()->hasRole('owner'))<select name="branch_id" required><option value="">Branch</option>@foreach($branches as $b)<option value="{{ $b->id }}">{{ $b->name }}</option>@endforeach</select>@else<input type="hidden" name="branch_id" value="{{ auth()->user()->branch_id }}">@endif<select name="product_variant_id" required><option value="">Product / size / colour / SKU</option>@foreach(\\App\\Models\\ProductVariant::with('product')->where('is_active',true)->orderBy('sku')->get() as $v)<option value="{{ $v->id }}">{{ $v->product->name }} — {{ $v->size }}/{{ $v->color }} ({{ $v->sku }})</option>@endforeach</select><select name="direction"><option value="in">Stock In</option><option value="out">Stock Out</option></select><input type="number" name="quantity" min="1" required placeholder="Quantity"><input type="number" name="reorder_level" min="0" placeholder="Low-stock alert at (optional)"><input name="notes" required placeholder="Reason"><button>Save Adjustment</button></form>@foreach($errors->all() as $e)<p style="color:#b42318">{{ $e }}</p>@endforeach</div><div class="card"><h2>Stock On Hand</h2><div style="overflow:auto"><table><tr><th>Branch</th><th>Product</th><th>Size</th><th>Colour</th><th>SKU</th><th>Qty</th><th>Reorder</th><th>Status</th></tr>@forelse($stocks as $s)<tr><td>{{ $s->branch->name }}</td><td>{{ $s->productVariant->product->name }}</td><td>{{ $s->productVariant->size }}</td><td>{{ $s->productVariant->color }}</td><td>{{ $s->productVariant->sku }}</td><td>{{ $s->quantity }}</td><td>{{ $s->reorder_level }}</td><td>{{ $s->quantity <= $s->reorder_level ? 'LOW STOCK' : 'OK' }}</td></tr>@empty<tr><td colspan="8">No stock records yet.</td></tr>@endforelse</table></div>{{ $stocks->links() }}</div></main></body></html>